import {
	Component,
	Event,
	type EventEmitter,
	Host,
	Prop,
	State,
	Watch,
	forceUpdate,
	h,
} from "@stencil/core";
import type { MarkedOptions } from "marked";

type DOMPurifyApi = {
	addHook: (hook: "afterSanitizeAttributes", cb: (node: Node) => void) => void;
	removeHook: (hook: "afterSanitizeAttributes") => void;
	sanitize: (source: string) => string;
};

type MarkdownModules = {
	DOMPurify: DOMPurifyApi;
	parse: typeof import("marked").parse;
};

let markdownModulesPromise: Promise<MarkdownModules> | undefined;

const loadMarkdownModules = async () => {
	if (!markdownModulesPromise) {
		markdownModulesPromise = Promise.all([
			import("dompurify"),
			import("marked"),
		]).then(([dompurifyModule, markedModule]) => ({
			DOMPurify: dompurifyModule.default,
			parse: markedModule.parse,
		}));
	}

	return markdownModulesPromise;
};

/**
 * @since 1.1.41
 * @status beta
 *
 */
@Component({
	tag: "hbr-markdown",
	styleUrl: "markdown.scss",
	shadow: true,
})
export class HbrMarkdown {
	baseRef: HTMLElement;
	private renderId = 0;
	private pendingEmitId = 0;
	/** content as markdown string */
	@Prop({ reflect: false }) content: string;

	/** set to true if content is HTML string */
	@Prop({ reflect: true }) parsed: false;

	/** callback function to be called after sanitizeAttributes */
	@Prop() afterSanitizeAttributes: undefined;

	/** set to true if content is already sanitized */
	@Prop() skipSanitize = false;

	/** marked options */
	@Prop() markedOptions: MarkedOptions = {};

	@State() renderedContent: string | null = null;

	/** Emitted after markdown did render. version: 2.9.12 */
	@Event({ eventName: "hbr-markdown-did-render" }) didRender: EventEmitter;

	async componentWillLoad() {
		await this.updateRenderedContent();
	}

	componentDidRender() {
		if (this.pendingEmitId !== 0 && this.pendingEmitId === this.renderId) {
			this.pendingEmitId = 0;
			this.didRender.emit({ base: this.baseRef });
		}
	}

	@Watch("afterSanitizeAttributes")
	@Watch("content")
	@Watch("markedOptions")
	@Watch("parsed")
	@Watch("skipSanitize")
	async updateRenderedContent() {
		const currentRenderId = ++this.renderId;

		if (!this.content) {
			this.renderedContent = null;
			this.pendingEmitId = currentRenderId;
			forceUpdate(this);
			return;
		}

		const { DOMPurify, parse } = await loadMarkdownModules();

		if (currentRenderId !== this.renderId) {
			return;
		}

		const pendingHookWork: Promise<unknown>[] = [];

		if (this.afterSanitizeAttributes) {
			DOMPurify.addHook("afterSanitizeAttributes", (node: Node) => {
				// @ts-ignore
				const result = this.afterSanitizeAttributes(node);
				if (result && typeof (result as Promise<unknown>).then === "function") {
					pendingHookWork.push(result as Promise<unknown>);
				}
			});
		}

		try {
			const purifiedString = this.skipSanitize
				? this.content
				: DOMPurify.sanitize(this.content);

			// Defensively await any async work the user-provided
			// afterSanitizeAttributes callback returned. DOMPurify hooks are
			// invoked synchronously and their return values are ignored, so
			// without this await an async callback's side effects could land
			// after didRender is emitted.
			if (pendingHookWork.length > 0) {
				await Promise.all(pendingHookWork);

				if (currentRenderId !== this.renderId) {
					return;
				}
			}

			this.renderedContent = this.parsed
				? purifiedString
				: (parse(purifiedString, this.markedOptions) as string);

			this.pendingEmitId = currentRenderId;
			forceUpdate(this);
		} finally {
			if (this.afterSanitizeAttributes) {
				DOMPurify.removeHook("afterSanitizeAttributes");
			}
		}
	}

	render() {
		return (
			<Host>
				<div
					ref={(ref) => {
						this.baseRef = ref;
					}}
					class="prose"
					part="base"
					innerHTML={this.renderedContent}
				/>
			</Host>
		);
	}
}
